props.rules:
& h4 { margin: 4px 0 8px; font-size: 12px; letter-spacing: 1px; text-transform: uppercase; color: #3ee6c4; }
& .row { display: grid; grid-template-columns: 1fr 72px 72px; gap: 6px; margin-bottom: 6px; font-size: 13px; color: #9aa0b8; align-items: center; }
& .row b { font-weight: normal; color: #eef0fa; background: #ffffff0d; border-radius: 6px; padding: 4px 8px; font-family: ui-monospace, monospace; font-size: 12px; }
& .row b.w { grid-column: span 2; }
& p { font-size: 13px; line-height: 1.55; color: #9aa0b8; margin: 14px 0 0; }
& i { font-style: normal; color: #eef0fa; font-family: ui-monospace, monospace; font-size: 12px; }
